entries[47470] = { ["name"] = "Hinrichten", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVersucht, einen verwundeten Feind zu erledigen. Verursacht (1142 + Attack power * 0.2) Schaden und wandelt alle verfügbaren Wutpunkte in jeweils 30 zusätzlichen Schaden um (bis zu Maximalkosten von 30 Wut). Kann nur auf Feinde angewandt werden, die weniger als 20% Gesundheit besitzen." }
entries[47471] = { ["name"] = "Hinrichten", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVersucht, einen verwundeten Feind zu erledigen. Verursacht (1456 + Attack power * 0.2) Schaden und wandelt alle verfügbaren Wutpunkte in jeweils 38 zusätzlichen Schaden um (bis zu Maximalkosten von 30 Wut). Kann nur auf Feinde angewandt werden, die weniger als 20% Gesundheit besitzen." }
