entries[47476] = { ["name"] = "Strangulieren", ["text"] = "1 Blutrune / -1 Runenmacht 30 Meter Reichweite\nSpontanzauber 2 min Abklingzeit\nWürgt einen Feind und bringt ihn bis zu 5 sec lang zum Schweigen. Das Zauberwirken von Nichtspieler-Zielen ist ebenfalls 3 sec lang unterbrochen." }
