entries[47480] = { ["name"] = "Hauen", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nEin körperlicher Angriff, der einen Feind verletzt.\n\nVerursacht pro Rasereipunkt mehr Schaden:\n1 Punkt: (Attack power * 40 * 0.01 + Attack power * 0.05)-(Attack power * 40 * 0.01 + Attack power * 0.10) Schaden\n2 Punkte: (Attack power * 40 * 0.01 + Attack power * 0.10)-(Attack power * 40 * 0.01 + Attack power * 0.20) Schaden\n3 Punkte: (Attack power * 40 * 0.01 + Attack power * 0.15)-(Attack power * 40 * 0.01 + Attack power * 0.30) Schaden\n4 Punkte: (Attack power * 40 * 0.01 + Attack power * 0.20)-(Attack power * 40 * 0.01 + Attack power * 0.40) Schaden\n5 Punkte: (Attack power * 40 * 0.01 + Attack power * 0.25)-(Attack power * 40 * 0.01 + Attack power * 0.50) Schaden" }
entries[47481] = { ["name"] = "Nagen", ["text"] = "30 Energie Nahkampfreichweite\nSofort 1 min Abklingzeit\nNagt dem Ziel eine Extremität ab, betäubt es 3 sec lang und fügt ihm Schaden zu." }
entries[47482] = { ["name"] = "Sprung", ["text"] = "10 Energie 5 - 30 Meter Reichweite\nSofort 20 sek. Abklingzeit\nSpringt hinter den angewählten Gegner oder Freund." }
entries[47484] = { ["name"] = "Zusammenkauern", ["text"] = "10 EnergieKanalisiert (Wirken in 10 sek.) 45 sek. Abklingzeit\nKauert sich verteidigend zusammen, verringert 10 sec lang den durch Nahkampfangriffe, Distanzangriffe und Zauber erlittenen Schaden um 50%." }
entries[47485] = { ["name"] = "Tödlicher Stoß", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin heimtückischer Stoß, der Waffenschaden plus 320 verursacht und das Ziel verwundet sowie die Wirksamkeit jeglicher Heilung 10 sec lang um 50% verringert." }
