entries[47487] = { ["name"] = "Schildschlag", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber 6 sek. Abklingzeit\nVerpasst dem Ziel einen heftigen Schlag mit Eurem Schild und verursacht 837 to 879 Schaden, modifiziert durch Euren Schildblockwert. Bannt zusätzlich 1 magischen Effekt des Ziels. Erzeugt außerdem ein hohes Maß an Bedrohung." }
