entries[47833] = { ["name"] = "Saat der Verderbnis", ["text"] = "Unbegrenzte Reichweite\nSofort\nPflanzt dem feindlichen Ziel eine Saat der Verderbnis ein, die im Verlauf von 18 sec 1296 Schattenschaden verursacht. Wenn das Ziel insgesamt 1296 Schaden erleidet oder stirbt, verursacht die Saat bei allen anderen Feinden im Umkreis von 15 Metern um das Ziel 1383 to 1607 Schattenschaden. Auf jedem Ziel kann pro Hexenmeister nur ein Verderbniszauber aktiv sein." }
