entries[47855] = { ["name"] = "Seelendieb", ["text"] = "14% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 sec lang insgesamt 710 Schattenschaden. Besitzt das Ziel 25% Gesundheit oder weniger, verursacht 'Seelendieb' den vierfachen Schaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Jedes Mal, wenn 'Seelendieb' Schaden verursacht, besteht ebenfalls eine Chance, dass ein Seelensplitter erzeugt wird. Seelensplitter werden für andere Zauber benötigt." }
entries[47856] = { ["name"] = "Lebenslinie", ["text"] = "277 Gesundheit und 182 pro Sek. 45 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 520 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
