entries[47859] = { ["name"] = "Todesmantel", ["text"] = "23% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nVerursacht 686 Schattenschaden und das betroffene Ziel läuft 3 sec lang voller Entsetzen davon. Der Zaubernde erhält 300% des verursachten Schadens in Gesundheit." }
