entries[47863] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 sec lang 1440 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[47864] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 sec lang 1740 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[47865] = { ["name"] = "Fluch der Elemente", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 min lang seinen Arkan-, Feuer-, Frost-, Natur- und Schattenwiderstand um 165. Erhöht außerdem den erlittenen Magieschaden des Ziels um 13%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[47867] = { ["name"] = "Fluch der Verdammnis", ["text"] = "15% von Grundmana 30 Meter Reichweite\nSofort 1 min Abklingzeit\nVerflucht das Ziel mit drohender Verdammnis und verursacht nach Ablauf von 1 min 7300 Schattenschaden. Wenn das Ziel Erfahrung oder Ehre gewährt und durch diesen Schaden stirbt, wird eine Verdammniswache beschworen. Kann nicht auf Spieler gewirkt werden." }
