entries[47883] = { ["name"] = "Seelensteinauferstehung", ["text"] = "30 Meter ReichweiteWirken in 3 sek. 15 min Abklingzeit\nSpeichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es sich mit 5300 Gesundheit und 4300 Mana wiederbeleben." }
entries[47884] = { ["name"] = "Seelenstein herstellen", ["text"] = "68% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen dämonischen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 5300 Gesundheit und 4300 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
